import api from '../utils/api';

export const authService = {
  async login(payload) {
    try {
      const { data } = await api.post('/auth/customer/login', payload);
      return data.data;
    } catch (error) {
      console.warn('Auth Error, using dummy login:', error.message);
      // For demo purposes, allow any login if backend is down
      const user = { _id: 'dummy-user-1', name: 'Demo User', email: payload.email };
      localStorage.setItem('shopzone_user', JSON.stringify(user));
      localStorage.setItem('shopzone_token', 'dummy-token');
      return { user, token: 'dummy-token' };
    }
  },
  async register(payload) {
    try {
      const { data } = await api.post('/auth/customer/register', payload);
      return data.data;
    } catch (error) {
      console.warn('Auth Error, using dummy register:', error.message);
      const user = { _id: 'dummy-user-1', name: payload.name, email: payload.email };
      return { user, token: 'dummy-token' };
    }
  },
  async me() {
    try {
      const { data } = await api.get('/auth/customer/me');
      return data.data.user;
    } catch (error) {
      const saved = localStorage.getItem('shopzone_user');
      return saved ? JSON.parse(saved) : null;
    }
  },
  async logout() {
    try {
      await api.post('/auth/customer/logout');
    } catch (e) {
      console.warn('Logout failed on server');
    }
    localStorage.removeItem('shopzone_user');
    localStorage.removeItem('shopzone_token');
  }
};
